import math
import sqlite3
from dataclasses import dataclass
from typing import Dict, List, Tuple, Optional

# ---- Vector / Graph clients ----
from pymilvus import connections, Collection
from neo4j import GraphDatabase

# Embedding model (you may swap with your own embedding service)
from sentence_transformers import SentenceTransformer


# =====================
# Fixed configuration (as required)
# =====================
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    "milvus_collections": {
        "reviews": "reviews",          # review text vectors
        "photos": "photo_vector",      # photo vectors
        "tips": "milvus_tip"           # tip text vectors
    },
    "milvus_host": "localhost",
    "milvus_port": "19530"
}

neo4j_config = {
    "neo4j_uri": "bolt://localhost:7687",
    "neo4j_auth": ("neo4j", "password")
}


# =====================
# Helper utilities
# =====================
@dataclass
class Business:
    business_id: str
    name: str
    address: str
    city: str
    state: str
    stars: float
    review_count: int
    categories: str


def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def safe_close(conn):
    try:
        conn.close()
    except Exception:
        pass


def ensure_milvus_connection():
    # idempotent connect
    connections.connect(
        alias="default",
        host=milvus_config["milvus_host"],
        port=milvus_config["milvus_port"],
    )


def get_collection(name: str) -> Collection:
    col = Collection(name)
    # load for search
    try:
        col.load()
    except Exception:
        # Some deployments auto-load; ignore
        pass
    return col


def embed_query(model: SentenceTransformer, text: str) -> List[float]:
    vec = model.encode([text], normalize_embeddings=True)
    return vec[0].tolist()


def chunk_list(xs: List[str], n: int) -> List[List[str]]:
    return [xs[i:i+n] for i in range(0, len(xs), n)]


# =====================
# Core logic
# =====================

def fetch_candidate_businesses(city: str = "Saint Louis", limit: int = 800) -> List[Business]:
    conn = connect_sqlite(sqlite_paths["business"])
    try:
        keywords = [
            "%Chinese%", "%Szechuan%", "%Sichuan%", "%Dim Sum%",
            "%Taiwanese%", "%Cantonese%", "%Hot Pot%", "%Noodles%"
        ]
        where_or = " OR ".join(["categories LIKE ?" for _ in keywords])
        sql = f"""
        SELECT business_id, name, address, city, state, stars, review_count, categories
        FROM business
        WHERE city LIKE ?
          AND ({where_or})
        ORDER BY review_count DESC
        LIMIT ?
        """
        params = [f"%{city}%", *keywords, limit]
        rows = conn.execute(sql, params).fetchall()
        out = []
        for r in rows:
            out.append(Business(
                business_id=r["business_id"],
                name=r["name"],
                address=r["address"],
                city=r["city"],
                state=r["state"],
                stars=float(r["stars"]) if r["stars"] is not None else 0.0,
                review_count=int(r["review_count"]) if r["review_count"] is not None else 0,
                categories=r["categories"] or ""
            ))
        return out
    finally:
        safe_close(conn)


def milvus_search_reviews(query_vec: List[float], topk: int = 2000):
    ensure_milvus_connection()
    col = get_collection(milvus_config["milvus_collections"]["reviews"])

    # Try common vector field names
    vec_field_candidates = ["embedding", "vector", "review_vector", "text_vector"]
    vec_field = None
    for f in vec_field_candidates:
        if f in [x.name for x in col.schema.fields]:
            vec_field = f
            break
    if vec_field is None:
        raise RuntimeError("Cannot find a vector field in Milvus 'reviews' collection. Tried: " + ",".join(vec_field_candidates))

    # Search params vary by index type; try a generic set.
    search_params = {"metric_type": "IP", "params": {"nprobe": 16}}

    # Request a few scalar fields if present
    output_fields = []
    for f in ["review_id", "business_id"]:
        if f in [x.name for x in col.schema.fields]:
            output_fields.append(f)

    res = col.search(
        data=[query_vec],
        anns_field=vec_field,
        param=search_params,
        limit=topk,
        output_fields=output_fields
    )

    hits = []
    for hit in res[0]:
        entity = getattr(hit, "entity", None)
        row = {
            "score": float(hit.score),
        }
        # entity.get("field") works in newer pymilvus
        if entity is not None:
            for f in output_fields:
                try:
                    row[f] = entity.get(f)
                except Exception:
                    pass
        hits.append(row)
    return hits


def milvus_search_tips(query_vec: List[float], topk: int = 1500):
    ensure_milvus_connection()
    col = get_collection(milvus_config["milvus_collections"]["tips"])

    vec_field_candidates = ["embedding", "vector", "tip_vector", "text_vector"]
    vec_field = None
    for f in vec_field_candidates:
        if f in [x.name for x in col.schema.fields]:
            vec_field = f
            break
    if vec_field is None:
        raise RuntimeError("Cannot find a vector field in Milvus 'milvus_tip' collection.")

    search_params = {"metric_type": "IP", "params": {"nprobe": 16}}

    output_fields = []
    for f in ["tip_id", "business_id"]:
        if f in [x.name for x in col.schema.fields]:
            output_fields.append(f)

    res = col.search(
        data=[query_vec],
        anns_field=vec_field,
        param=search_params,
        limit=topk,
        output_fields=output_fields
    )

    hits = []
    for hit in res[0]:
        entity = getattr(hit, "entity", None)
        row = {"score": float(hit.score)}
        if entity is not None:
            for f in output_fields:
                try:
                    row[f] = entity.get(f)
                except Exception:
                    pass
        hits.append(row)
    return hits


def map_reviews_to_business(review_ids: List[str]) -> Dict[str, List[sqlite3.Row]]:
    """Return business_id -> list of review rows (review_id, business_id, stars, text)."""
    if not review_ids:
        return {}
    conn = connect_sqlite(sqlite_paths["review"])
    try:
        out: Dict[str, List[sqlite3.Row]] = {}
        for chunk in chunk_list(review_ids, 900):
            placeholders = ",".join(["?"] * len(chunk))
            sql = f"""
            SELECT review_id, business_id, stars, text
            FROM review
            WHERE review_id IN ({placeholders})
            """
            rows = conn.execute(sql, chunk).fetchall()
            for r in rows:
                bid = r["business_id"]
                out.setdefault(bid, []).append(r)
        return out
    finally:
        safe_close(conn)


def map_tips_to_business(tip_ids: List[str]) -> Dict[str, List[sqlite3.Row]]:
    if not tip_ids:
        return {}
    conn = connect_sqlite(sqlite_paths["tip"])
    try:
        out: Dict[str, List[sqlite3.Row]] = {}
        for chunk in chunk_list(tip_ids, 900):
            placeholders = ",".join(["?"] * len(chunk))
            sql = f"""
            SELECT rowid as _rowid, user_id, business_id, text, date
            FROM tip
            WHERE rowid IN ({placeholders})
            """
            rows = conn.execute(sql, chunk).fetchall()
            for r in rows:
                bid = r["business_id"]
                out.setdefault(bid, []).append(r)
        return out
    finally:
        safe_close(conn)


def try_neo4j_enrich(business_ids: List[str]) -> Dict[str, float]:
    """Optional: returns business_id -> graph_score.

    This is schema-dependent; we attempt a very conservative query and fall back to empty.
    """
    if not business_ids:
        return {}

    driver = None
    try:
        driver = GraphDatabase.driver(neo4j_config["neo4j_uri"], auth=neo4j_config["neo4j_auth"])
        with driver.session() as session:
            # Try to count how many relationships each business has (a generic centrality proxy)
            # Requires nodes labeled :Business with property business_id.
            cypher = """
            UNWIND $bids AS bid
            MATCH (b:Business {business_id: bid})-[r]-()
            RETURN bid AS business_id, count(r) AS degree
            """
            result = session.run(cypher, bids=business_ids)
            out = {}
            for rec in result:
                out[rec["business_id"]] = float(rec["degree"])
            return out
    except Exception:
        return {}
    finally:
        try:
            if driver is not None:
                driver.close()
        except Exception:
            pass


def rank_authentic_chinese_in_stl(topn: int = 10):
    # 1) candidates from SQL
    candidates = fetch_candidate_businesses(city="Saint Louis", limit=800)
    cand_map = {b.business_id: b for b in candidates}
    cand_ids = list(cand_map.keys())

    if not candidates:
        print("No Chinese-related businesses found for Saint Louis in business.db")
        return

    # 2) embed query
    model = SentenceTransformer("sentence-transformers/all-MiniLM-L6-v2")
    review_query = "authentic Chinese food, traditional flavors, like in China, not Americanized, legit"
    tip_query = "authentic, traditional, legit, like China, real Chinese"
    review_vec = embed_query(model, review_query)
    tip_vec = embed_query(model, tip_query)

    # 3) vector search reviews
    review_hits = milvus_search_reviews(review_vec, topk=2500)

    # Collect review_ids if present; otherwise cannot map
    review_ids = [h.get("review_id") for h in review_hits if h.get("review_id")]
    reviews_by_business = map_reviews_to_business(review_ids)

    # Build review semantic score per business
    # We'll use max similarity among that business's matched reviews (robust and simple)
    review_score_by_bid: Dict[str, float] = {}
    best_review_snippet: Dict[str, str] = {}

    # If Milvus returned business_id directly, we can avoid SQLite mapping for scoring,
    # but still use SQLite to pull a snippet for explanation.
    # We'll compute scores from the hits we have.
    hit_by_review_id = {h.get("review_id"): h for h in review_hits if h.get("review_id")}

    for bid, rows in reviews_by_business.items():
        if bid not in cand_map:
            continue
        scores = []
        for r in rows:
            h = hit_by_review_id.get(r["review_id"])
            if h is None:
                continue
            scores.append(h["score"])
        if scores:
            review_score_by_bid[bid] = max(scores)
            # snippet from best-scoring review
            best_rid = max(rows, key=lambda rr: hit_by_review_id.get(rr["review_id"], {"score": -1e9})["score"])["review_id"]
            txt = None
            for rr in rows:
                if rr["review_id"] == best_rid:
                    txt = rr["text"]
                    break
            if txt:
                best_review_snippet[bid] = (txt[:220] + "...") if len(txt) > 220 else txt

    # 4) vector search tips (optional signal)
    tip_hits = milvus_search_tips(tip_vec, topk=2000)
    tip_ids = [h.get("tip_id") for h in tip_hits if h.get("tip_id")]

    tips_by_business = map_tips_to_business(tip_ids)
    tip_score_by_bid: Dict[str, float] = {}
    best_tip_snippet: Dict[str, str] = {}

    hit_by_tip_id = {h.get("tip_id"): h for h in tip_hits if h.get("tip_id")}

    for bid, rows in tips_by_business.items():
        if bid not in cand_map:
            continue
        scores = []
        for r in rows:
            h = hit_by_tip_id.get(r["_rowid"])
            if h is None:
                continue
            scores.append(h["score"])
        if scores:
            tip_score_by_bid[bid] = max(scores)
            best_row = max(rows, key=lambda rr: hit_by_tip_id.get(rr["_rowid"], {"score": -1e9})["score"])
            txt = best_row["text"]
            if txt:
                best_tip_snippet[bid] = (txt[:220] + "...") if len(txt) > 220 else txt

    # 5) optional graph enrichment
    graph_degree = try_neo4j_enrich(cand_ids)

    # 6) final ranking
    # Combine:
    # - semantic score from reviews (primary)
    # - semantic score from tips (secondary)
    # - business stars
    # - popularity damped by log(review_count)
    # - optional graph degree (small weight)
    def final_score(b: Business) -> float:
        rs = review_score_by_bid.get(b.business_id, 0.0)
        ts = tip_score_by_bid.get(b.business_id, 0.0)
        pop = math.log1p(b.review_count)
        gd = graph_degree.get(b.business_id, 0.0)
        return (
            2.0 * rs +
            0.8 * ts +
            0.4 * float(b.stars) +
            0.15 * pop +
            0.02 * gd
        )

    ranked = sorted(candidates, key=final_score, reverse=True)

    # Print top results with explanations
    print("Top places for authentic Chinese food in Saint Louis (data-driven):")
    print("=" * 80)
    shown = 0
    for b in ranked:
        if shown >= topn:
            break
        # Require at least some semantic signal OR high rating count
        if review_score_by_bid.get(b.business_id, 0.0) <= 0 and tip_score_by_bid.get(b.business_id, 0.0) <= 0:
            continue

        shown += 1
        print(f"#{shown}  {b.name}")
        print(f"     Address: {b.address}, {b.city}, {b.state}")
        print(f"     Stars/Reviews: {b.stars} ({b.review_count} reviews)")
        print(f"     Categories: {b.categories}")
        print(f"     Semantic(authentic) review score: {review_score_by_bid.get(b.business_id, 0.0):.4f}")
        print(f"     Semantic(authentic) tip score:    {tip_score_by_bid.get(b.business_id, 0.0):.4f}")
        if b.business_id in best_review_snippet:
            print(f"     Matched review snippet: {best_review_snippet[b.business_id]}")
        if b.business_id in best_tip_snippet:
            print(f"     Matched tip snippet:    {best_tip_snippet[b.business_id]}")
        print("-" * 80)

    if shown == 0:
        print("No semantically matched reviews/tips found. Try increasing Milvus topk or ensure Milvus collections contain review_id/tip_id.")


if __name__ == "__main__":
    # You can tune topn as needed
    rank_authentic_chinese_in_stl(topn=10)

