import math
import sqlite3
from collections import defaultdict

# Optional deps
try:
    from pymilvus import connections, Collection, utility
except Exception:
    connections = None
    Collection = None
    utility = None

try:
    from neo4j import GraphDatabase
except Exception:
    GraphDatabase = None

try:
    from sentence_transformers import SentenceTransformer
except Exception:
    SentenceTransformer = None


def dict_factory(cursor, row):
    d = {}
    for idx, col in enumerate(cursor.description):
        d[col[0]] = row[idx]
    return d


def connect_sqlite(path: str):
    conn = sqlite3.connect(path)
    conn.row_factory = dict_factory
    return conn


def execute_sql(conn, sql, params=None):
    cur = conn.cursor()
    cur.execute(sql, params or [])
    return cur.fetchall()


def safe_log1p(x):
    try:
        return math.log1p(max(0, x))
    except Exception:
        return 0.0


def minmax_norm(values):
    if not values:
        return {}
    vmin = min(values)
    vmax = max(values)
    if vmax == vmin:
        return {i: 0.0 for i in range(len(values))}
    return {i: (v - vmin) / (vmax - vmin) for i, v in enumerate(values)}


def main(top_n=10):
    # ---- Required configuration (per instructions) ----
    sqlite_paths = {
        "business": "D:/Yelp-JSON/db/sqlite3/business.db",
        "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
        "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
        "review": "D:/Yelp-JSON/db/sqlite3/review.db",
        "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
        "user": "D:/Yelp-JSON/db/sqlite3/user.db"
    }

    milvus_cfg = {
        'milvus_collections': {
            'reviews': 'reviews',
            'photos': 'photo_vector',
            'tips': 'milvus_tip'
        },
        'milvus_host': 'localhost',
        'milvus_port': '19530'
    }

    neo4j_cfg = {
        'neo4j_uri': 'bolt://localhost:7687',
        'neo4j_auth': ('neo4j', 'password')
    }

    # ---- Step 1: SQL filter candidates in Boise ----
    biz_conn = connect_sqlite(sqlite_paths['business'])

    # Broad-ish BBQ + American filters; you can tighten/loosen LIKE clauses as needed.
    sql_candidates = """
    SELECT business_id, name, address, city, state, postal_code, stars, review_count, categories
    FROM business
    WHERE city = ? AND state = ? AND is_open = 1
      AND (categories LIKE ? OR categories LIKE ?)
      AND (categories LIKE ? OR categories LIKE ?)
    ORDER BY review_count DESC
    LIMIT 200
    """

    candidates = execute_sql(
        biz_conn,
        sql_candidates,
        ["Boise", "ID", "%Barbeque%", "%BBQ%", "%American (Traditional)%", "%American (New)%"]
    )

    if not candidates:
        # Fallback: drop the American filter if too strict
        sql_candidates2 = """
        SELECT business_id, name, address, city, state, postal_code, stars, review_count, categories
        FROM business
        WHERE city = ? AND state = ? AND is_open = 1
          AND (categories LIKE ? OR categories LIKE ?)
        ORDER BY review_count DESC
        LIMIT 200
        """
        candidates = execute_sql(biz_conn, sql_candidates2, ["Boise", "ID", "%Barbeque%", "%BBQ%"])

    cand_by_id = {c['business_id']: c for c in candidates}
    cand_ids = list(cand_by_id.keys())

    # ---- Step 2: Vector search for 'authentic' signal (optional, with graceful degradation) ----
    auth_by_business = defaultdict(lambda: {"hit_count": 0, "score_sum": 0.0, "best_score": None, "review_ids": []})
    vector_enabled = False

    query_text = (
        "authentic American traditional BBQ in Boise, smoky brisket, ribs, pulled pork, real pit, smoked"
    )

    if connections and Collection and SentenceTransformer:
        try:
            connections.connect(host=milvus_cfg['milvus_host'], port=milvus_cfg['milvus_port'])
            coll_name = milvus_cfg['milvus_collections']['reviews']
            if not utility.has_collection(coll_name):
                raise RuntimeError(f"Milvus collection not found: {coll_name}")

            coll = Collection(coll_name)
            coll.load()

            # Find vector field + dimension
            vec_field = None
            vec_dim = None
            for f in coll.schema.fields:
                # pymilvus DataType is available via f.dtype, but keep generic
                if str(f.dtype).lower().find('float_vector') != -1:
                    vec_field = f.name
                    vec_dim = int(getattr(f, 'params', {}).get('dim', 0) or 0)
                    break

            if not vec_field or not vec_dim:
                raise RuntimeError("Could not infer vector field/dim from Milvus schema.")

            model = SentenceTransformer('all-MiniLM-L6-v2')
            emb = model.encode([query_text], normalize_embeddings=True)
            if emb.shape[1] != vec_dim:
                raise RuntimeError(f"Embedding dim mismatch: model={emb.shape[1]} vs milvus={vec_dim}.")

            # Infer metric type if possible
            metric_type = 'IP'
            try:
                idx = coll.indexes
                if idx:
                    metric_type = idx[0].params.get('metric_type', metric_type)
            except Exception:
                pass

            search_params = {
                "metric_type": metric_type,
                "params": {"nprobe": 10}
            }

            # Choose an id field for returned hits
            id_field = None
            for f in coll.schema.fields:
                if getattr(f, 'is_primary', False):
                    id_field = f.name
                    break
            # Common fallback
            if not id_field:
                for guess in ['review_id', 'id']:
                    if any(ff.name == guess for ff in coll.schema.fields):
                        id_field = guess
                        break
            if not id_field:
                raise RuntimeError("Could not infer primary id field (e.g., review_id) from Milvus schema.")

            top_k_reviews = 300
            res = coll.search(
                data=emb,
                anns_field=vec_field,
                param=search_params,
                limit=top_k_reviews,
                output_fields=[id_field]
            )

            # Extract review ids + similarity scores
            hits = []
            for hit in res[0]:
                rid = None
                try:
                    rid = hit.entity.get(id_field)
                except Exception:
                    try:
                        rid = hit.get(id_field)
                    except Exception:
                        rid = None
                if rid is None:
                    continue
                hits.append((str(rid), float(hit.score)))

            if hits:
                vector_enabled = True

                # Map review_id -> business_id via SQLite review.db
                rev_conn = connect_sqlite(sqlite_paths['review'])

                # SQLite has parameter limit; chunk IN queries
                chunk = 900
                hit_map = {}
                for i in range(0, len(hits), chunk):
                    sub = hits[i:i+chunk]
                    ids = [h[0] for h in sub]
                    q_marks = ','.join(['?'] * len(ids))
                    sql_map = f"SELECT review_id, business_id FROM review WHERE review_id IN ({q_marks})"
                    rows = execute_sql(rev_conn, sql_map, ids)
                    for r in rows:
                        hit_map[str(r['review_id'])] = r['business_id']

                # Aggregate to candidate businesses only
                for rid, score in hits:
                    bid = hit_map.get(str(rid))
                    if not bid or bid not in cand_by_id:
                        continue
                    agg = auth_by_business[bid]
                    agg['hit_count'] += 1
                    agg['score_sum'] += score
                    agg['review_ids'].append(rid)
                    if agg['best_score'] is None or score > agg['best_score']:
                        agg['best_score'] = score

        except Exception as e:
            # Degrade gracefully
            vector_enabled = False
            auth_by_business = defaultdict(lambda: {"hit_count": 0, "score_sum": 0.0, "best_score": None, "review_ids": []})
            print(f"[WARN] Vector step skipped: {e}")

    else:
        print("[WARN] Vector step unavailable: missing pymilvus and/or sentence-transformers.")

    # ---- Step 3: Rank candidates combining business metadata + authenticity signal ----
    # Prepare arrays for normalization
    biz_ids = cand_ids
    stars_list = [float(cand_by_id[bid].get('stars') or 0.0) for bid in biz_ids]
    rc_list = [int(cand_by_id[bid].get('review_count') or 0) for bid in biz_ids]

    auth_strength_list = []
    for bid in biz_ids:
        a = auth_by_business.get(bid)
        if not a or a['hit_count'] == 0:
            auth_strength_list.append(0.0)
        else:
            # simple combined strength: avg similarity * log1p(hit_count)
            avg_sim = a['score_sum'] / max(1, a['hit_count'])
            auth_strength_list.append(avg_sim * safe_log1p(a['hit_count']))

    stars_norm = minmax_norm(stars_list)
    rc_norm = minmax_norm([safe_log1p(x) for x in rc_list])
    auth_norm = minmax_norm(auth_strength_list)

    ranked = []
    for idx, bid in enumerate(biz_ids):
        b = cand_by_id[bid]
        s = stars_norm[idx]
        r = rc_norm[idx]
        a = auth_norm[idx] if vector_enabled else 0.0

        # weights: stars + popularity + authenticity (only if enabled)
        score = 0.60 * s + 0.25 * r + (0.15 * a if vector_enabled else 0.0)

        ranked.append({
            "business_id": bid,
            "name": b.get('name'),
            "address": b.get('address'),
            "city": b.get('city'),
            "state": b.get('state'),
            "postal_code": b.get('postal_code'),
            "stars": b.get('stars'),
            "review_count": b.get('review_count'),
            "categories": b.get('categories'),
            "auth_hit_count": int(auth_by_business[bid]['hit_count']) if bid in auth_by_business else 0,
            "auth_best_score": auth_by_business[bid]['best_score'] if bid in auth_by_business else None,
            "final_score": score
        })

    ranked.sort(key=lambda x: x['final_score'], reverse=True)
    top = ranked[:top_n]

    # ---- Step 4 (optional): Neo4j signals ----
    if GraphDatabase and top:
        try:
            driver = GraphDatabase.driver(neo4j_cfg['neo4j_uri'], auth=neo4j_cfg['neo4j_auth'])
            business_ids = [t['business_id'] for t in top]
            cypher = """
            MATCH (b:Business)<-[:REVIEWED]-(u:User)
            WHERE b.business_id IN $business_ids
            RETURN b.business_id AS business_id,
                   count(DISTINCT u) AS n_users,
                   sum(CASE WHEN coalesce(u.elite,false)=true THEN 1 ELSE 0 END) AS elite_reviews
            """
            with driver.session() as session:
                rows = session.run(cypher, business_ids=business_ids).data()
            gmap = {r['business_id']: r for r in rows}
            for t in top:
                g = gmap.get(t['business_id'])
                if g:
                    t['graph_n_users'] = g.get('n_users')
                    t['graph_elite_reviews'] = g.get('elite_reviews')
        except Exception as e:
            print(f"[WARN] Neo4j step skipped: {e}")

    # ---- Output ----
    print(f"Found {len(candidates)} BBQ candidates in Boise. Vector enabled: {vector_enabled}. Showing top {len(top)}.")
    for i, t in enumerate(top, 1):
        line1 = f"{i}. {t['name']}  (stars={t['stars']}, reviews={t['review_count']}, score={t['final_score']:.3f})"
        line2 = f"   {t['address']}, {t['city']}, {t['state']} {t['postal_code']}"
        line3 = f"   categories: {t['categories']}"
        if vector_enabled:
            line4 = f"   authenticity_hits={t['auth_hit_count']} best_sim={t['auth_best_score']}"
        else:
            line4 = ""
        print(line1)
        print(line2)
        print(line3)
        if line4:
            print(line4)


if __name__ == '__main__':
    main(top_n=10)

